(() => {
 'use strict';
 const f=window.EVAL_FIXTURES, m=f.menu, app=document.getElementById('app');
 const params=new URLSearchParams(location.search), theme=params.get('theme');
 if(['light','dark'].includes(theme))document.documentElement.dataset.theme=theme;
 document.documentElement.dataset.display=params.get('display')==='tv'?'tv':'laptop';
 const states=['main','compose','pending','offline','empty','accepted'];
 let screen=states.includes(params.get('screen'))?params.get('screen'):'main';
 let step='choose',recipient='',note='',requestStatus='none';
 const read=()=>{try{return JSON.parse(sessionStorage.getItem('rota-request')||'null')}catch{return null}};
 const saved=read();if(saved){requestStatus=saved.status;note=saved.note||'';recipient=saved.recipient||'';}
 if(screen==='pending'||screen==='accepted'){requestStatus=screen;recipient=m.handoverTo;}
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const first=n=>n.split(' ')[0], initials=n=>n.split(' ').map(x=>x[0]).join('');
 const date=new Date(f.now);const day=new Intl.DateTimeFormat('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'}).format(date);
 const time=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'}).format(date);
 const minutes=t=>t.split(':').reduce((h,n,i)=>h+Number(n)*(i?1:60),0);
 const progress=(minutes(time)-minutes(m.shiftStart))/(minutes(m.shiftEnd)-minutes(m.shiftStart));
 document.documentElement.style.setProperty('--shift-progress',Math.max(0,Math.min(1,progress))*100+'%');
 const mark='<svg class="mark" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M3 6h9a4 4 0 0 1 0 8H8M17 14H8a4 4 0 0 1 0-8" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>';
 function store(){try{sessionStorage.setItem('rota-request',JSON.stringify({status:requestStatus,recipient,note}))}catch{}}
 function announce(t){document.getElementById('announcer').textContent=t}
 function go(next){screen=next;const p=new URLSearchParams(location.search);p.set('screen',next);try{history.replaceState(null,'','?'+p)}catch{}render();document.querySelector('h1').focus();}
 function footer(){return `<footer><span>${escape(m.user)}</span><span>All times UTC</span></footer>`}
 function back(label='Schedule'){return `<button class="back" data-action="back">‹ ${label}</button>`}
 function handoff(accepted=false){return `<div class="handoff" aria-label="${accepted?'Priya is now responsible':'Jamie remains responsible; Priya has not accepted'}"><div class="handoff-person"><div class="handoff-name">${first(m.user)}</div><div class="status-label ${accepted?'':'responsible'}">${accepted?'Handed over':'Responsible now'}</div></div><span class="handoff-arrow" aria-hidden="true">→</span><div class="handoff-person"><div class="handoff-name">${first(m.handoverTo)}</div><div class="status-label ${accepted?'responsible':''}">${accepted?'Responsible now':screen==='pending'?'Awaiting acceptance':'After acceptance'}</div></div></div>`}
 function shiftDetails(accepted=false){return `<dl class="details"><dt>Rotation</dt><dd>${m.rotation}</dd><dt>Coverage</dt><dd>${accepted?'Now':'On acceptance'} – ${m.shiftEnd} UTC</dd><dt>Date</dt><dd>${day}</dd></dl>`}
 function roster(accepted){return `<div class="section-head"><h2>Also on call</h2><span class="sub">Current roster</span></div><ul class="roster">${m.roster.filter(p=>p.name!==m.user).map(p=>`<li class="person"><span class="avatar" aria-hidden="true">${initials(p.name)}</span><div><strong>${escape(p.name)}</strong><div class="sub">${escape(p.role)}</div></div><span class="person-time">Until ${p.until}</span></li>`).join('')}</ul>`}
 function main(offline=false){const accepted=requestStatus==='accepted'&&!offline;return `<div class="date"><span class="eyebrow">${day}</span><span class="sub">${offline?'Saved '+time:time} UTC</span></div><h1 tabindex="-1">${offline?'Last known schedule':accepted?"You’re off call.":"You’re on call."}</h1>${offline?`<p class="notice caution">Offline. Saved at ${time} UTC on ${day}. Changes may be missing.</p>`:''}<section class="hero" aria-label="${offline?'Saved':'Current'} primary shift"><div class="hero-top">${offline?'':'<span class="dot" aria-hidden="true"></span>'}<span class="rotation">${m.rotation}</span></div><div class="shift-time"><span class="${offline?'rotation':'big-time'}">${offline?m.shiftStart+' – '+m.shiftEnd:m.shiftEnd}</span><span class="sub">${offline?'UTC':'Shift ends · UTC'}</span></div>${offline?'':`<div class="track" aria-hidden="true"><div class="track-fill"></div></div><div class="times"><span>${m.shiftStart}</span><span>Now ${time}</span><span>${m.shiftEnd}</span></div>`}<div class="owner"><strong>${escape(accepted?m.handoverTo:m.user)}</strong><span class="sub">${accepted?'On call':offline?'Last known primary':'You · Primary'}</span></div></section>${offline?'<button class="primary wide" data-action="retry">Try reconnecting</button><p class="sub field-note">Handovers are unavailable offline.</p>':accepted?'<button class="secondary wide" data-action="accepted">View handover</button>':requestStatus==='pending'?'<button class="secondary wide" data-action="pending">View pending handover <span class="arrow" aria-hidden="true">→</span></button>':'<button class="primary wide" data-action="compose">Hand over your shift <span class="arrow" aria-hidden="true">→</span></button>'}${roster(accepted)}`}
 function compose(){if(step==='review')return `${back('Edit handover')}<p class="eyebrow step">Review handover</p><h1 tabindex="-1">Pass the shift to Priya?</h1>${handoff()}${shiftDetails()}${note?`<div class="summary"><h2>Handover note</h2><p class="note-text">${escape(note)}</p></div>`:''}<p class="notice">You remain responsible until ${escape(m.handoverTo)} accepts.</p><div class="actions"><button class="secondary" data-action="cancel">Cancel</button><button class="primary" data-action="send">Send request</button></div>`;
 return `${back()}<p class="eyebrow step">${escape(m.rotation)}</p><h1 tabindex="-1">Hand over your shift</h1><p class="intro">Request cover for the rest of today’s shift.</p><div class="form-section"><fieldset class="recipient-field"><legend>Hand over to</legend><label class="recipient-choice" for="recipient"><span class="avatar" aria-hidden="true">${initials(m.handoverTo)}</span><span>${escape(m.handoverTo)}</span><input type="radio" id="recipient" name="recipient" value="${escape(m.handoverTo)}" ${recipient?'checked':''}></label></fieldset><p class="sub field-note">Coverage ends at ${m.shiftEnd} UTC.</p></div><div class="form-section"><label class="field-label" for="note">Handover note <span class="sub">(optional)</span></label><textarea id="note" maxlength="300" rows="2" placeholder="Anything Priya should know?">${escape(note)}</textarea></div><p class="notice">You stay on call until your teammate accepts.</p><div class="actions"><button class="secondary" data-action="cancel">Cancel</button><button class="primary" id="review" data-action="review" ${recipient?'':'disabled'}>Review handover</button></div>`}
 function pending(){return `${back()}<p class="eyebrow step">Handover requested</p><h1 tabindex="-1">Waiting for Priya</h1><p class="intro">The shift stays with you for now.</p>${handoff()}${shiftDetails()}<p class="notice caution">You’re still on call. Keep responding until Priya accepts.</p>${note?`<p class="note-text">${escape(note)}</p>`:''}<div class="actions"><button class="secondary" data-action="withdraw">Cancel request</button></div><p class="sub field-note">Requested from ${escape(m.handoverTo)}.</p>`}
 function accepted(){return `${back()}<div class="success-symbol" aria-hidden="true">✓</div><h1 tabindex="-1">Priya has the shift.</h1><p class="intro">Your handover has been accepted.</p>${handoff(true)}${shiftDetails(true)}<p class="notice">${escape(m.handoverTo)} is now responsible for ${m.rotation}. You’re off call.</p><button class="primary wide" data-action="back">Back to schedule</button>`}
 function empty(){return `${back()}<div class="empty-body"><svg class="empty-symbol" viewBox="0 0 48 48" fill="none" aria-hidden="true"><rect x="7" y="10" width="34" height="31" rx="5" stroke="currentColor" stroke-width="1.5"/><path d="M15 6v8m18-8v8M7 20h34m-26 9h7m4 0h7" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg><h1 tabindex="-1">No schedule yet</h1><p>There are no shifts to show for ${escape(m.rotation)}.</p><p>No on-call responsibility is assigned in this view. Check with your rotation owner before relying on it.</p><button class="secondary wide" data-action="refresh">Refresh schedule</button></div>`}
 function render(){app.innerHTML=`<header>${mark}<span class="brand">${escape(m.product)}</span><span class="header-detail">On call</span></header><div class="content">${screen==='compose'?compose():screen==='pending'?pending():screen==='accepted'?accepted():screen==='empty'?empty():main(screen==='offline')}</div>${footer()}`;
 app.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action)));
 const sel=document.getElementById('recipient');if(sel)sel.addEventListener('change',()=>{recipient=sel.checked?sel.value:'';document.getElementById('review').disabled=!recipient});
 const field=document.getElementById('note');if(field)field.addEventListener('input',()=>note=field.value);
 }
 function act(action){switch(action){case'compose':step='choose';recipient='';note='';go('compose');break;case'review':if(!recipient)return;step='review';render();document.querySelector('h1').focus();break;case'back':if(screen==='compose'&&step==='review'){step='choose';render();document.getElementById('recipient').focus()}else go('main');break;case'cancel':go('main');break;case'send':requestStatus='pending';store();go('pending');announce('Handover requested. You remain responsible until Priya accepts.');break;case'withdraw':requestStatus='none';store();go('main');announce('Request cancelled. You remain on call.');break;case'pending':go('pending');break;case'accepted':go('accepted');break;case'retry':announce('Still offline. Saved schedule retained.');document.querySelector('[data-action="retry"]').textContent='Still offline · Try again';break;case'refresh':announce('No schedule is available in this offline prototype.');document.querySelector('[data-action="refresh"]').textContent='No schedule available';break;}}
 window.addEventListener('message',e=>{if(e.source===parent&&e.data?.type==='rota:accept'&&requestStatus==='pending'){requestStatus='accepted';store();go('accepted');announce('Priya accepted. You are now off call.')}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&['compose','pending','accepted'].includes(screen)){e.preventDefault();act('back')}});
 render();
})();
